    "answer": "При возникновении тяжелого несчастного случая, смертельного или группового:\n1. Работодатель в течение суток направляет извещение в трудовую инспекцию, прокуратуру, территориальный орган Ростехнадзора, ФСС и родственникам.\n2. Приказом формируется комиссия (не менее 3 человек) под председательством государственного инспектора труда или Ростехнадзора.\n3. Срок расследования тяжелых/смертельных случаев — до 30 календарных дней.\n4. По результатам составляется Акт формы Н-1 (в 3-х экземплярах) с определением причин и виновных лиц.",
