    "answer": "Для всех электроустановок должны быть составлены однолинейные электрические схемы первичных соединений для всех нормальных и аварийных режимов. Все изменения в схемах, внесенные в процессе эксплуатации, должны немедленно фиксироваться в оперативной документации и наноситься на схемы за подписью ответственного за электрохозяйство с указанием его должности и даты. Схемы должны пересматриваться не реже одного раза в 3 года с отметкой на них о проверке.",
